= document.getElementById(id); const rect = win.getBoundingClientRect(); offsetX = e.clientX - rect.left; offsetY = e.clientY - rect.top; } document.addEventListener('mousemove', e => { if (!arrastrando) return; const win = document.getElementById(arrastrando); win.style.left = (e.clientX - offsetX) + 'px'; win.style.top = (e.clientY - offsetY) + 'px'; }); document.addEventListener('mouseup', () => arrastrando = null); // === CONEXIÓN WEBSOCKET === function conectarServidor() { const direccion = 'ws://localhost:8080'; conexionWS = new WebSocket(direccion); conexionWS.onopen = () => { document.getElementById('estadoServidor').textContent = '✅ Conectado al servidor'; document.getElementById('estadoServidor').className = 'status-conectado'; }; conexionWS.onmessage = (evento) => { const datos = JSON.parse(evento.data); procesarMensaje(datos); }; conexionWS.onclose = () => { document.getElementById('estadoServidor').textContent = 'Desconectado'; document.getElementById('estadoServidor').className = 'status-desconectado'; dispositivoConectado = null; }; conexionWS.onerror = (err) => { document.getElementById('estadoServidor').textContent = 'Error de conexión'; alert('No se pudo conectar al servidor. ¿Está ejecutándose?'); }; } function desconectarServidor() { if (conexionWS) conexionWS.close(); } function procesarMensaje(datos) { switch(datos.tipo) { case 'tu-id': miID = datos.id; document.getElementById('miID').value = miID; break; case 'solicitud-conexion': document.getElementById('alertaVinculacion').classList.add('show'); break; case 'llamada-entrante': document.getElementById('numLlamador').textContent = datos.numero; document.getElementById('alertaLlamada').classList.add('show'); break; case 'conectado': dispositivoConectado = datos.desde; document.getElementById('estadoLlamada').textContent = '✅ Conectado — Vinculación activa'; document.getElementById('estadoLlamada').className = 'status-conectado'; document.getElementById('estadoVinculacion').textContent = '✅ Vinculación establecida'; document.getElementById('estadoVinculacion').className = 'status-conectado'; break; } } function enviarMensaje(datos) { if (conexionWS && conexionWS.readyState === WebSocket.OPEN) { conexionWS.send(JSON.stringify(datos)); } } // === FUNCIONES DE LLAMADAS === function hacerLlamada() { const numero = document.getElementById('numLlamada').value.trim(); const destino = document.getElementById('idDestino').value.trim(); if (!numero || !destino) { alert('Escribe número y ID del destino'); return; } document.getElementById('estadoLlamada').textContent = 'Llamando...'; document.getElementById('estadoLlamada').className = 'status-esperando'; enviarMensaje({ tipo: 'iniciar-llamada', destino: destino, numero: numero }); } function contestar() { document.getElementById('alertaLlamada').classList.remove('show'); enviarMensaje({ tipo: 'contestar' }); } function rechazarLlamada() { document.getElementById('alertaLlamada').classList.remove('show'); enviarMensaje({ tipo: 'rechazar' }); document.getElementById('estadoLlamada').textContent = 'Rechazada'; } function colgar() { enviarMensaje({ tipo: 'colgar' }); document.getElementById('estadoLlamada').textContent = 'Desconectado'; document.getElementById('estadoLlamada').className = 'status-desconectado'; document.getElementById('estadoVinculacion').textContent = 'Esperando aceptación...'; document.getElementById('estadoVinculacion').className = 'status-esperando'; } // === FUNCIONES DE MENSAJES === function enviarPorWhatsApp() { const nombre = document.getElementById('nombreCliente').value; const correo = document.getElementById('correoCliente').value; const telefono = document.getElementById('telExtranjero').value; const mensaje = document.getElementById('textoMensaje').value; if (!telefono) { alert('Escribe el teléfono del cliente'); return; } const enlaceVinculacion = const textoCompleto = encodeURIComponent( 📦 Estimado(a) ${nombre || 'Cliente'}:
${mensaje}

🔗 ${enlaceVinculacion} ); window.open( ' blank'); alert('✅ Mensaje preparado con enlace de vinculación'); } function enviarPorSMS() { alert('📱 SMS listo — incluye enlace de vinculación'); } // === FUNCIONES DE VINCULACIÓN === function simularAceptar() { document.getElementById('alertaVinculacion').classList.add('show'); } function aceptarVinculacion() { document.getElementById('alertaVinculacion').classList.remove('show'); enviarMensaje({ tipo: 'aceptar-vinculacion' }); } function rechazarVinculacion() { document.getElementById('alertaVinculacion').classList.remove('show'); enviarMensaje({ tipo: 'rechazar-vinculacion' }); } function copiarEnlace() { const correo = document.getElementById('correoCliente').value || 'cliente@ejemplo.com'; const enlace = || 'local'}; navigator.clipboard.writeText(enlace).then(() => { alert('✅ Enlace copiado: ' + enlace); }); } function enviarVinculacion() { const destino = document.getElementById('idDestino').value.trim(); if (!destino) { alert('Escribe el ID del dispositivo destino'); return; } enviarMensaje({ tipo: 'solicitud-vinculacion', destino: destino, correo: document.getElementById('correoCliente').value }); alert('✅ Solicitud enviada'); } // Abrir conexión automáticamente abrirVentana('conexion'); abrirVentana('llamada'); abrirVentana('mensaje'); abrirVentana('vinculacion'); ); }); // === SERVIDOR WEBSOCKET === const servidorWS = new WebSocket.Server({ port: PUERTO }); const dispositivosConectados = new Map(); console.log('🟢 Servidor Iphoends iniciando...'); console.log(📡 WebSocket: ws://localhost:${PUERTO}); console.log(🌐 Interfaz: servidorWS.on('connection', (conexion) => { const idDispositivo = generarID(); dispositivosConectados.set(idDispositivo, { conexion, estado: 'conectado', emparejadoCon: null }); console.log(✅ Dispositivo conectado: ${idDispositivo}); // Enviar su ID al cliente conexion.send(JSON.stringify({ tipo: 'tu-id', id: idDispositivo })); conexion.on('message', (mensaje) => { try { const datos = JSON.parse(mensaje.toString()); manejarMensaje(idDispositivo, datos); } catch (e) { console.log('⚠️ Mensaje inválido:', mensaje); } }); conexion.on('close', () => { console.log(❌ Desconectado: ${idDispositivo}); dispositivosConectados.delete(idDispositivo); }); conexion.on('error', (err) => { console.log(⚠️ Error en ${idDispositivo}:, err.message); }); }); function generarID() { return 'IPH-' + Math.random().toString(36).substring(2, 10).toUpperCase(); } function manejarMensaje(origen, datos) { const dispOrigen = dispositivosConectados.get(origen); if (!dispOrigen) return; const destino = datos.destino; switch (datos.tipo) { case 'iniciar-llamada': if (dispositivosConectados.has(destino)) { dispositivosConectados.get(destino).conexion.send(JSON.stringify({ tipo: 'llamada-entrante', desde: origen, numero: datos.numero })); console.log(📞 Llamada de ${origen} → ${destino}); } else { dispOrigen.conexion.send(JSON.stringify({ tipo: 'error', mensaje: 'Dispositivo no encontrado' })); } break; case 'solicitud-vinculacion': if (dispositivosConectados.has(destino)) { dispositivosConectados.get(destino).conexion.send(JSON.stringify({ tipo: 'solicitud-conexion', desde: origen, correo: datos.correo })); console.log(🔗 Vinculación de ${origen} → ${destino}); } break; case 'contestar': if (destino && dispositivosConectados.has(destino)) { dispOrigen.emparejadoCon = destino; dispositivosConectados.get(destino).emparejadoCon = origen; dispositivosConectados.get(destino).conexion.send(JSON.stringify({ tipo: 'conectado', desde: origen })); dispOrigen.conexion.send(JSON.stringify({ tipo: 'conectado', desde: destino })); console.log(✅ Conexión establecida: ${origen} ↔ ${destino}); } break; case 'aceptar-vinculacion': if (destino && dispositivosConectados.has(destino)) { dispOrigen.emparejadoCon = destino; dispositivosConectados.get(destino).emparejadoCon = origen; dispositivosConectados.get(destino).conexion.send(JSON.stringify({ tipo: 'vinculacion-aceptada', desde: origen })); dispOrigen.conexion.send(JSON.stringify({ tipo: 'conectado', desde: destino })); } break; case 'rechazar': case 'rechazar-vinculacion': if (destino && dispositivosConectados.has(destino)) { dispositivosConectados.get(destino).conexion.send(JSON.stringify({ tipo: 'solicitud-rechazada', desde: origen })); } dispOrigen.emparejadoCon = null; if (dispositivosConectados.has(destino)) { dispositivosConectados.get(destino).emparejadoCon = null; } break; case 'colgar': const par = dispOrigen.emparejadoCon; if (par && dispositivosConectados.has(par)) { dispositivosConectados.get(par).conexion.send(JSON.stringify({ tipo: 'colgado' })); dispositivosConectados.get(par).emparejadoCon = null; } dispOrigen.emparejadoCon = null; console.log(📞 Llamada finalizada: ${origen}); break; case 'datos-remitente': if (destino && dispositivosConectados.has(destino)) { dispositivosConectados.get(destino).conexion.send(JSON.stringify({ tipo: 'datos-cliente', nombre: datos.nombre, correo: datos.correo, telefono: datos.telefono })); } break; } } servidorHTTP.listen(PUERTO HTTP, () => { console.log(🌐 Interfaz disponible en: }); { "name": "iphoends-servidor", "version": "1.0.0", "description": "Servidor de conexión Iphoends — Windows 98", "main": "servidor-iphoends.js", "scripts": { "iniciar": "node servidor-iphoends.js" }, "dependencies": { "ws": "^8.14.0" } } cd iphoends-servidor npm install npm run iniciar

