ce(ServeDir::new(root).not found service(not found)); let (tx, rx) = oneshot::channel:: (); runtime().spawn(async move { let listener = tokio::net::TcpListener::from std(listener) .expect("could not adopt the fixture listener"); let served = axum::serve(listener, app) .with graceful shutdown(async { let = rx.await; }) .await; if let Err(e) = served { eprintln!("fixture server stopped: {e}"); } }); Self { addr, shutdown: Some(tx), } } pub(crate) fn origin(&self) -> String { format!(" self.addr) } pub(crate) fn url(&self, path: &str) -> String { format!("{}/{}", self.origin(), path.trim start matches("/")) } } impl std::fmt::Debug for FixtureServer { fn fmt(&self, f: &mut std::fmt::Formatter ) -> std::fmt::Result { f.debug struct("FixtureServer") .field("addr", &self.addr) .finish non exhaustive() } } impl Drop for FixtureServer { fn drop(&mut self) { if let Some(tx) = self.shutdown.take() { let = tx.send(()); } } } pub(crate) fn fixtures() -> &'static FixtureServer { static SERVER: OnceLock = OnceLock::new(); SERVER.get or init(|| FixtureServer::start(fixture root())) } fn fixture root() -> PathBuf { match std::env::var("FIXTURE ROOT") { Ok(root) => PathBuf::from(root), Err( ) => PathBuf::from(env!("CARGO MANIFEST DIR")).join("tests/fixtures"), } } pub(crate) fn fixture origin() -> String { fixtures().origin() } pub(crate) fn fixture url(path: &str) -> String { fixtures().url(path) } pub(crate) async fn goto fixture(driver: &WebDriver, path: &str) -> WebDriverResult { driver.goto(fixture url(path).as str()).await } // runtime.rs use std::sync::OnceLock; use tokio::runtime::{Handle, Runtime}; pub(crate) fn runtime() -> &'static Runtime { static RT: OnceLock = OnceLock::new(); RT.get or init(|| { let mut builder = tokio::runtime::Builder::new multi thread(); builder.enable all().thread name("test-rt"); if let Some(n) = env usize("TEST RT WORKER THREADS") { builder.worker threads(n.max(1)); } builder .build() .expect("failed to build the shared test runtime") }) } pub(s